26	/// One session the owner can share to, as the sidebar shows it.
27	nonisolated struct ShareSession: Codable, Identifiable, Equatable, Sendable {
28	    let key: String
29	    let title: String
30	    let folder: String?
31	    let running: Bool
32	    let queueDepth: Int
33	    let lastActivity: Double
34	    var id: String { key }
35	
36	    /// What the dashboard's sidebar shows: `surface` (a copy of `mode`) of
37	    /// "" or "orchestrator" (0.7.0's filter; 0.6.0 also showed "crew"), and
38	    /// never a `member-*` key, which the gateway reserves (409). Newest
39	    /// activity first.
40	    static func list(from slots: [[String: Any]], folders: [String: String]) -> [ShareSession] {
41	        slots.compactMap { s -> ShareSession? in
42	            guard let key = s["key"] as? String, !key.isEmpty, !key.hasPrefix("member-") else { return nil }
43	            let surface = (s["surface"] as? String) ?? (s["mode"] as? String) ?? ""
44	            guard surface == "" || surface == "orchestrator" else { return nil }
45	            let title = (s["title"] as? String).flatMap { $0.isEmpty ? nil : $0 } ?? key
46	            return ShareSession(key: key, title: title,
47	                                folder: (s["folder_id"] as? String).flatMap { folders[$0] },
48	                                running: (s["running"] as? Bool) ?? false,
49	                                queueDepth: (s["queue_depth"] as? Int) ?? 0,
50	                                lastActivity: (s["last_activity_ts"] as? Double)
51	                                    ?? Double((s["last_activity_ts"] as? Int) ?? 0))
52	        }
53	        .sorted { $0.lastActivity > $1.lastActivity }
54	    }
55	}
