58	    static let currentVersion = 1
59	    /// Older than this, a gateway's list is not offered (F18 §9 Q6: 24 h).
60	    static let staleAfter: TimeInterval = 24 * 3600
61	
62	    struct Destination: Codable, Equatable, Sendable {
63	        var slotKey: String
64	        var slotTitle: String?
65	        var at: Date
66	    }
67	
68	    struct Gateway: Codable, Equatable, Sendable {
69	        var origin: String
70	        /// The host, for the drop-down.
71	        var label: String
72	        var fetchedAt: Date
73	        var sessions: [ShareSession]
74	        var lastDestination: Destination?
75	
76	        func isStale(now: Date) -> Bool { now.timeIntervalSince(fetchedAt) > ShareMirror.staleAfter }
77	    }
78	
79	    var version: Int = ShareMirror.currentVersion
80	    /// The gateway the app shows now.
81	    var current: String?
82	    var gateways: [Gateway] = []
83	
84	    func gateway(_ origin: String) -> Gateway? { gateways.first { $0.origin == origin } }
85	
86	    /// Replaces `origin`'s entry with a fresh listing and makes it current.
87	    mutating func record(origin: String, label: String, sessions: [ShareSession], at now: Date) {
88	        let last = gateway(origin)?.lastDestination
89	        gateways.removeAll { $0.origin == origin }
90	        gateways.insert(Gateway(origin: origin, label: label, fetchedAt: now,
91	                                sessions: sessions, lastDestination: last), at: 0)
92	        current = origin
93	    }
94	
95	    mutating func remember(origin: String, _ destination: Destination) {
96	        guard let i = gateways.firstIndex(where: { $0.origin == origin }) else { return }
97	        gateways[i].lastDestination = destination
98	    }
99	
100	    /// Drops every gateway not in `origins` (F18 §6.1: a gateway's entry
101	    /// goes when the gateway is removed from the workspace). Returns whether
102	    /// anything changed.
103	    @discardableResult
104	    mutating func retain(origins: [String]) -> Bool {
105	        let keep = Set(origins)
106	        let before = gateways.count
107	        gateways.removeAll { !keep.contains($0.origin) }
108	        if let c = current, !keep.contains(c) { current = nil }
109	        return gateways.count != before
110	    }
