112	    // MARK: - What the drop-down sees
113	
114	    /// Why the list is empty, in the owner's words (F18 §5), or nil when
115	    /// `offered` has something to show.
116	    static func emptyReason(_ mirror: ShareMirror?, now: Date) -> String? {
117	        guard let mirror, !mirror.gateways.isEmpty else {
118	            return "Open Latchkey once so it can list your sessions."
119	        }
120	        let fresh = mirror.gateways.filter { !$0.isStale(now: now) }
121	        guard !fresh.isEmpty else {
122	            let newest = mirror.gateways.map(\.fetchedAt).max() ?? .distantPast
123	            let hours = max(1, Int(now.timeIntervalSince(newest) / 3600))
124	            return "Latchkey's session list is \(hours) h old. Open Latchkey to refresh it."
125	        }
