// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  ShareTestHooks.swift
//  Latchkey
//
//  Test builds only (R15). XCUITest cannot drive the App Intent or a share
//  extension, so documents enter the inbox here, written exactly as the
//  intent writes them -- through the same admission (F3 §7, "Seeding
//  without the extension"):
//
//    -UITestResetShare            an empty inbox, no remembered session and
//                                 no session mirror
//    -UITestSeedShare <spec>      kind:bytes[:age=<days>d][:name=<file>][:dest=<key>]
//                                 kind pdf (a `%PDF-` header) or bin; the
//                                 name defaults to shared.<kind>; dest
//                                 addresses it to <key> on the test gateway
//                                 (F18 §6.2), as the Shortcut's drop-down does
//    -UITestIntentDeliver         with a dest= seed: the item goes the
//                                 Shortcut's way, `ShareDelivery.performIntent`
//                                 in this process (F18 §4 C), rather than
//                                 through the inbox and the picker
//

#if LATCHKEY_TEST_HOOKS
import Foundation

enum ShareTestHooks {
    /// Applies the hooks. Returns the seeded item, its destination and its
    /// payload file when `-UITestIntentDeliver` asks for the intent's path;
    /// the caller runs it once it exists. Otherwise the seed is in the store.
    static func apply(store: ShareInbox, defaults: ShareDefaults, mirror: ShareMirrorStore,
                      onSeeded: () -> Void) -> (item: ShareItem, destination: ShareDestination, payload: URL)? {
        if TestHooks.flag("-UITestResetShare") {
            store.removeAll()
            defaults.removeAll()
            mirror.removeAll()
        }
        guard let spec = TestHooks.value("-UITestSeedShare") else { return nil }
        let parts = spec.split(separator: ":").map(String.init)
        guard parts.count >= 2, ["pdf", "bin"].contains(parts[0]), let bytes = Int64(parts[1]), bytes >= 0 else {
            logger.log("Share: -UITestSeedShare \(spec) is not kind:bytes[:age=Nd][:name=…][:dest=…]")
            return nil
        }
        var age: TimeInterval = 0
        var name = "shared.\(parts[0])"
        var destination: ShareDestination?
        for p in parts.dropFirst(2) {
            if p.hasPrefix("age="), p.hasSuffix("d"), let d = Double(p.dropFirst(4).dropLast()) { age = d * 86400 }
            if p.hasPrefix("name=") { name = String(p.dropFirst(5)) }
            if p.hasPrefix("dest="), let home = TestHooks.value("-UITestHomePage"),
               let origin = GatewayAddress.origin(of: home) {
                destination = ShareDestination(origin: origin, slotKey: String(p.dropFirst(5)),
                                               slotTitle: String(p.dropFirst(5)), chosenAt: Date())
            }
        }
        let id = UUID().uuidString
        var item = ShareItem(id: id, kind: .document, url: nil, title: nil, text: nil, note: nil,
                             filename: ShareItem.sanitisedFilename(name),
                             utType: parts[0] == "pdf" ? "com.adobe.pdf" : "public.data",
                             byteCount: bytes, createdAt: Date().addingTimeInterval(-age), source: .intent)
        item.destination = destination
        // What the intent does: the size first, before any byte exists.
        if case .refused(let r) = ShareInboxPolicy.admit(byteCount: bytes, fileExtension: item.fileExtension,
                                                          inboxCount: store.summary().count,
                                                          inboxBytes: store.summary().bytes) {
            logger.log("Share: refused \(id) at capture: \(ShareDelivery.describe(r))")
            return nil
        }
        let file = FileManager.default.temporaryDirectory.appending(path: "seed-\(id)")
        guard FileManager.default.createFile(atPath: file.path, contents: nil),
              let handle = try? FileHandle(forWritingTo: file) else { return nil }
        // One 1 MiB block, built once: the 50 MB seed is 50 writes of it.
        let block = Data((0..<(1 << 20)).map { UInt8(truncatingIfNeeded: $0 &* 31 &+ 7) })
        var left = bytes
        var first = true
        while left > 0 {
            var chunk = block.prefix(Int(min(left, Int64(block.count))))
            if first, parts[0] == "pdf" {
                let header = Data("%PDF-1.4\n".utf8)
                chunk.replaceSubrange(0..<min(header.count, chunk.count), with: header.prefix(chunk.count))
            }
            first = false
            try? handle.write(contentsOf: chunk)
            left -= Int64(chunk.count)
        }
        try? handle.close()
        if let destination, TestHooks.flag("-UITestIntentDeliver") {
            // The intent's path admits it itself (an APFS clone of the seed
            // file); the seed file is left for it and is in tmp anyway.
            item.destination = nil
            return (item, destination, file)
        }
        defer { try? FileManager.default.removeItem(at: file) }
        do {
            try store.add(item, payloadFile: file)
            onSeeded()
            logger.log("Share: received \(id) (document, \(bytes) B) via test seed\(destination == nil ? "" : ", addressed")")
        } catch {
            logger.log("Share: the test seed was not stored: \(error)")
        }
        return nil
    }
}
#endif

    app = try await launchSignedIn(seed: "pdf:1024:dest=obsidian")
    defer { app.terminate() }
    XCTAssertTrue(element(app, "share-session-notes").appears(within: 30), "the picker comes up instead")
    XCTAssertTrue(element(app, "share-picker").exists, "as a picker, not a send")
    let notice = element(app, "share-notice")
    XCTAssertTrue(notice.exists, "the owner is told which session went")
    XCTAssertTrue(notice.label.contains("obsidian") && notice.label.contains("isn't there any more"), notice.label)
    XCTAssertEqual(element(app, "share-destination-selected").label, "none", "nothing preselected")
    XCTAssertFalse(element(app, "share-send").isEnabled, "no Send without a pick")
    state = try await gatewayState()
    XCTAssertEqual(counter(state, "share_posts"), 1, "nothing more was posted")
    XCTAssertEqual(violations(state), 0, "no post to the stale key: \(state["violations"] ?? [])")
}

/// F18 §4 C, the Shortcut's run in the app's process: with the node up
/// and the page signed in from the last launch, the item is listed,
/// verified and posted by `performIntent` with no sheet at all, and the
/// phase times are logged under `ShareIntent:` (test-session.sh checks
/// the line). Then the session is gone: the run hands over to the
/// foreground, which shows the picker with the "queued for" line and
/// posts nothing. Shown able to fail by skipping the verify in
/// `deliver`: the post to the unlisted key is a recorded violation.
func testTheIntentDeliversInProcessWithoutASheetAndHandsOverWhenTheSessionIsGone() async throws {
    var app = try await launchSignedIn()
    app.terminate()
    // Signed in from the last launch: the cookie is in the kept web data.
    app = launch(seed: "pdf:1024:dest=obsidian", reset: false, intent: true)
    let awaited = try await lastResult(app, timeout: 60)
    XCTAssertEqual(awaited, "sent:obsidian")
    XCTAssertFalse(element(app, "share-picker").exists, "no picker")
    XCTAssertFalse(element(app, "share-delivery").exists, "no sheet at all: the run was in-process")
    var state = try await gatewayState()
    XCTAssertEqual(counter(state, "share_posts"), 1)
    XCTAssertEqual(violations(state), 0, "\(state["violations"] ?? [])")
    let navs = state["navigations"] as? [[String: Any]] ?? []
    XCTAssertTrue(navs.contains { $0["sid"] as? String == "obsidian" }, "the page was moved to the session: \(navs)")
    XCTAssertEqual(inboxCount(app), 0)
    app.terminate()

    _ = try await Self.post("\(Self.gatewayControl)/__slots?keys=notes,plan")
    app = launch(seed: "pdf:1024:dest=obsidian", reset: false, intent: true)
    defer { app.terminate() }
    XCTAssertTrue(element(app, "share-session-notes").appears(within: 45), "handed over: the picker comes up")
    let notice = element(app, "share-notice")
    XCTAssertTrue(notice.exists && notice.label.contains("obsidian"), "the owner is told which session went: \(notice.label)")
    XCTAssertEqual(element(app, "share-destination-selected").label, "none")
    state = try await gatewayState()
    XCTAssertEqual(counter(state, "share_posts"), 1, "nothing more was posted")
    XCTAssertEqual(violations(state), 0, "no post to the stale key: \(state["violations"] ?? [])")
}

/// The other hand-over: signed out, the run cannot finish in the
/// background. The item waits, addressed, the sign-in sheet says so,
/// and after sign-in it is sent with no picker and no further tap.
func testTheIntentHandsOverForSignInAndTheShareThenGoesByItself() async throws {
    let app = launch(seed: "pdf:1024:dest=obsidian", intent: true)
    defer { app.terminate() }
    XCTAssertTrue(element(app, "token-sheet").appears(within: 30), "signed out: the sign-in sheet")
    let waiting = element(app, "share-waiting-count")
    XCTAssertTrue(waiting.appears(within: 10))
    XCTAssertEqual(waiting.label, "1", "the addressed item waits for sign-in")
    let beforeSignIn = try await gatewayState()
    XCTAssertEqual(counter(beforeSignIn, "share_posts"), 0, "nothing posted before sign-in")
    try await signIn(app)
    let awaited = try await lastResult(app, timeout: 45)
    XCTAssertEqual(awaited, "sent:obsidian", "sent without a pick or a tap")
    XCTAssertFalse(element(app, "share-picker").exists, "no picker")
    let state = try await gatewayState()
    XCTAssertEqual(counter(state, "share_posts"), 1)
    XCTAssertEqual(violations(state), 0)
}

// MARK: - Stage 2: the share sheet's app row

/// F3 §7, "The share sheet route (stage 2)" -- fragile by nature: it
/// drives Safari and the system share sheet, whose layout is Apple's.
/// A page is shared from Safari to "Latchkey"; the extension saves it to
/// the App Group inbox and sends nothing; the app, brought back, has the
/// item from `source: extension` and delivers it like any other.
func testTheShareSheetSavesForTheAppAndTheAppSendsIt() async throws {
    let app = try await launchSignedIn()
    defer { app.terminate() }
    let page = "\(Self.gatewayControl)/ext-share-probe"
    let safari = XCUIApplication(bundleIdentifier: "com.apple.mobilesafari")
    safari.launch()
    XCUIDevice.shared.system.open(URL(string: page)!)
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    if springboard.buttons["Open"].waitForExistence(timeout: 2) { springboard.buttons["Open"].tap() }
    XCTAssertTrue(safari.wait(for: .runningForeground, timeout: 15), "Safari is in front")
    try await Task.sleep(for: .seconds(2))

    // Share: a toolbar button on older layouts; on iOS 26 it is in the
    // page menu, the leading button of the address bar.
    let share = safari.buttons.matching(NSPredicate(format: "identifier == 'ShareButton' OR label == 'Share'")).firstMatch
    if !share.waitForExistence(timeout: 3) {
        let menu = safari.buttons.matching(NSPredicate(
            format: "identifier CONTAINS[c] 'PageMenu' OR identifier CONTAINS[c] 'PageFormat' OR label CONTAINS[c] 'Page Menu' OR label == 'More'")).firstMatch
        XCTAssertTrue(menu.waitForExistence(timeout: 5),
                      "Safari's page menu; its buttons: \(safari.buttons.allElementsBoundByIndex.prefix(30).map { "\($0.identifier)|\($0.label)" })")
        menu.tap()
    }
    XCTAssertTrue(share.waitForExistence(timeout: 5),
                  "Safari offers Share; on screen: \(safari.buttons.allElementsBoundByIndex.prefix(40).map { "\($0.identifier)|\($0.label)" })")
    share.tap()

    // The app row. New extensions may sit behind "More" at its end.
    let row = safari.descendants(matching: .any).matching(NSPredicate(format: "label == 'Latchkey'")).firstMatch
    if !row.waitForExistence(timeout: 8) {
        let moreApps = safari.descendants(matching: .any).matching(NSPredicate(format: "label == 'More'")).firstMatch
        if moreApps.exists { moreApps.tap() }
    }
    XCTAssertTrue(row.waitForExistence(timeout: 8), "Latchkey is in the share sheet's app row (the extension is built in)")
    row.tap()

    let save = safari.descendants(matching: .any)["share-capture-save"]
    XCTAssertTrue(save.waitForExistence(timeout: 15), "the extension's sheet offers Save for Latchkey")
    save.tap()
    let saved = safari.descendants(matching: .any)["share-capture-saved"]
    let savedLabel = snapshotLabel(saved, within: 10)
    XCTAssertNotNil(savedLabel, "it says Saved. Open Latchkey to send it.")
    XCTAssertTrue(savedLabel?.contains("Open Latchkey") == true, savedLabel ?? "<never shown>")
    let before = try await gatewayState()
    XCTAssertEqual(counter(before, "share_posts"), 0, "the extension sent nothing")
    _ = saved.waitForNonExistence(timeout: 5)

    app.activate()
    let source = element(app, "share-item-source")
    XCTAssertTrue(source.waitForExistence(timeout: 30), "the app brings the saved share up")
    XCTAssertEqual(source.label, "extension", "written by the extension, to the group inbox")
    try pick(app, "obsidian")
    element(app, "share-send").tap()
    let awaitedExt = try await lastResult(app)
    XCTAssertEqual(awaitedExt, "sent:obsidian")
    let state = try await gatewayState()
    let message = ((state["posts"] as? [[String: Any]])?.first?["message"] as? String) ?? ""
    XCTAssertTrue(message.contains(page), "the post carries the shared URL: \(message)")
    XCTAssertEqual(violations(state), 0)
}

// MARK: - Helpers

/// `intent`: the seed goes the Shortcut's way, `ShareDelivery.performIntent`
/// in the app's process (F18 §4 C), not through the inbox and the picker.
private func launch(seed: String? = nil, reset: Bool = true, intent: Bool = false) -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments = (reset ? ["-UITestResetWorkspaces", "-UITestResetShare"] : []) + [
        "-UITestHomePage", Self.gateway,
        "-TestStatusFixture", OfflineHarnessTests.fixture(suffix: "tail-scale.ts.net", peers: ["gw"]),
        "-TestProxyEndpoint", OfflineHarnessTests.proxyEndpoint,
        "-TestProxyCredential", OfflineHarnessTests.proxyCredential,
        "-UITestKeepWebData",
    ] + (seed.map { ["-UITestSeedShare", $0] } ?? []) + (intent ? ["-UITestIntentDeliver"] : [])
    app.launch()
    return app
}

private func launchSignedIn(seed: String? = nil) async throws -> XCUIApplication {
    let app = launch(seed: seed)
    XCTAssertTrue(element(app, "token-sheet").appears(within: 30), "signed out at first")
    try await signIn(app)
    return app
}

/// Opens a share URL as another app would. The system may ask first.
///
/// It has not asked in any run on record, so waiting out the whole 3 s for
/// the question cost 3 s a share (F14). Stop as soon as the app shows
/// the share instead: its picker, or its signed-out wait. Only when a
/// picker was already up, and so proves nothing, is the 3 s paid.
private func share(_ app: XCUIApplication, _ url: String) {
    let pickerWasUp = element(app, "share-picker").exists
    XCUIDevice.shared.system.open(URL(string: url)!)
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    let open = springboard.buttons["Open"]
    let deadline = Date().addingTimeInterval(3)
    while Date() < deadline {
        if open.exists { open.tap(); return }
        if !pickerWasUp, element(app, "share-picker").exists || element(app, "share-waiting-count").exists { return }
        Thread.sleep(forTimeInterval: 0.1)
    }
}

/// Waits for the picker's list, then picks `key`.
private func pick(_ app: XCUIApplication, _ key: String,
                  file: StaticString = #filePath, line: UInt = #line) throws {
    let row = element(app, "share-session-\(key)")
    XCTAssertTrue(row.appears(within: 30), "the picker lists \(key)", file: file, line: line)
    // The picker is a sheet; its rows are in the tree from its first frame.
    row.tapWhenSettled(in: app, file: file, line: line)
    XCTAssertEqual(element(app, "share-destination-selected").label, key, file: file, line: line)
}

/// The outcome of the share just sent: the sheet's result while it is up,
/// else the counted instrument once the sheet has gone.
private func lastResult(_ app: XCUIApplication, timeout: Double = 40) async throws -> String {
    let deadline = Date().addingTimeInterval(timeout)
    let before = (try? element(app, "share-last-result").snapshot())?.label ?? "none"
    while Date() < deadline {
        if let r = try? element(app, "share-result").snapshot(), !r.label.isEmpty { return r.label }
        if !element(app, "share-picker").exists, let last = try? element(app, "share-last-result").snapshot(),
           last.label != "none", last.label != before {
            return last.label
        }
        try await Task.sleep(for: .milliseconds(200))
    }
    return "no result within \(Int(timeout)) s"
}

/// The inbox count, read with no sheet up (a sheet hides what is under it).
private func inboxCount(_ app: XCUIApplication) -> Int {
    // After a sent or queued result the sheet closes itself 2 s later
    // (ShareDelivery.finish). A Cancel tap aimed at it then can find it in
    // the tree and gone by the tap, which fails the test (seen under the
    // load of eight shards, F14): wait that close out instead, and let
    // presentations settle before looking.
    if let r = try? element(app, "share-result").snapshot(),
       r.label.hasPrefix("sent:") || r.label.hasPrefix("queued:") {
        _ = element(app, "share-picker").disappears(within: 10)
    }
    _ = app.settles(within: 10)
    if element(app, "share-picker").exists, element(app, "share-cancel").exists {
        element(app, "share-cancel").tap()
    }
    _ = element(app, "share-picker").disappears(within: 5)
    let marker = element(app, "share-inbox-count")
    guard marker.appears(within: 5) else { return -1 }
    return Int(marker.label) ?? -1
}

private func signIn(_ app: XCUIApplication) async throws {
    let minted = try JSONSerialization.jsonObject(
        with: try await Self.post("\(Self.gatewayControl)/__mint?kind=cli")) as? [String: Any]
    let url = try XCTUnwrap(minted?["url"] as? String)
    UIPasteboard.general.string = url
    let paste = element(app, "token-paste-button").exists
        ? element(app, "token-paste-button")
        : app.buttons["Paste"].firstMatch
    XCTAssertTrue(paste.appears(within: 10), "the sheet offers Paste")
    // Callers come here as soon as the sheet exists, i.e. mid-slide.
    paste.tapWhenSettled(in: app)
    XCTAssertTrue(element(app, "token-sheet").disappears(within: 30), "signed in")
}

/// The element's label from one snapshot, taken as soon as it exists;
/// nil if it never did. `exists` and then `.label` are two queries, and
/// a sheet that dismisses itself between them fails the test on the
/// second; `snapshot()` throws instead (F14: seen under shard load).
private func snapshotLabel(_ e: XCUIElement, within timeout: TimeInterval) -> String? {
    let deadline = Date().addingTimeInterval(timeout)
    repeat {
        if let s = try? e.snapshot() { return s.label }
        Thread.sleep(forTimeInterval: 0.1)
    } while Date() < deadline
    return nil
}

private func element(_ app: XCUIApplication, _ id: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: id).firstMatch
}

private func gatewayState() async throws -> [String: Any] {
    try JSONSerialization.jsonObject(with: try await Self.get("\(Self.gatewayControl)/__state")) as? [String: Any] ?? [:]
}

private func counter(_ state: [String: Any], _ name: String,
                     file: StaticString = #filePath, line: UInt = #line) -> Int {
    let counters = state["counters"] as? [String: Any] ?? [:]
    guard let value = counters[name] as? Int else {
        XCTFail("the fake gateway reports no counter named \(name)", file: file, line: line)
        return 0
    }
    return value
}

private func violations(_ state: [String: Any]) -> Int {
    (state["violations"] as? [Any])?.count ?? -1
}

